"use client";

import { useState, type CSSProperties } from "react";
import { LikeBurst, type BurstEffect } from "./burst";
import { HeartIcon } from "./heart";
import { LIKE_CSS } from "./like-css";
import { Odometer } from "./odometer";
import { playLikeSound } from "./sound";

/**
 * Faithful port of Bencho's "Like" press block (defaults: 1,300 likes, Bloom
 * burst at 50, red heart, 22 px corner). Everything is local: the heart path,
 * the odometer, the particle geometry and a Web Audio copy of `pop` / `tock`.
 */
const START = 1300;
const BURST = 0.5;
const EFFECT: BurstEffect = "Bloom";

export default function Demo() {
  const [liked, setLiked] = useState(false);
  const [burstKey, setBurstKey] = useState(0);
  const count = START + (liked ? 1 : 0);

  function handleClick() {
    const next = !liked;
    setLiked(next);

    if (next) {
      setBurstKey((key) => key + 1);
      playLikeSound("pop");
    } else {
      playLikeSound("tock");
    }
  }

  return (
    <div className="like-demo w-[240px] max-w-full">
      <style>{LIKE_CSS}</style>

      <div className="grid h-[130px] w-full place-items-center rounded-2xl border border-black/[0.04] bg-[#f7f7f6] dark:border-white/[0.06] dark:bg-[#0a0a0a]">
        <button
          type="button"
          aria-pressed={liked}
          aria-label={`${liked ? "Unlike" : "Like"}. ${count.toLocaleString("en-US")} likes`}
          onClick={handleClick}
          className="like-button flex h-11 items-center gap-2 rounded-[22px] bg-white pl-4 pr-5 text-base font-medium tracking-[-0.01em] text-[#17181a] transition duration-[220ms] ease-[cubic-bezier(0.22,1,0.36,1)] [-webkit-tap-highlight-color:transparent] hover:bg-[#fcfcfc] active:scale-[0.96] dark:bg-[#262626] dark:text-white dark:hover:bg-[#2d2d2d]"
        >
          <span className="relative grid h-5 w-5 place-items-center">
            <span
              key={liked ? "on" : "off"}
              className={`relative z-[1] grid ${
                liked
                  ? EFFECT === "Bloom"
                    ? "like-glyph-on text-[#e5484d]"
                    : "like-glyph-pop text-[#e5484d]"
                  : ""
              }`}
            >
              <HeartIcon filled={liked} />
            </span>

            {liked && BURST > 0 ? (
              <span
                key={burstKey}
                aria-hidden="true"
                className="like-burst pointer-events-none absolute left-1/2 top-1/2"
                style={{ "--fly": BURST } as CSSProperties}
              >
                <LikeBurst effect={EFFECT} fly={BURST} />
              </span>
            ) : null}
          </span>

          <Odometer value={count} up={liked} />
        </button>
      </div>
    </div>
  );
}

import type { CSSProperties } from "react";

export type BurstEffect = "Bloom" | "Firework";

/** Bencho's confetti palette, kept verbatim. */
const PALETTE = [
  "#f48ea7",
  "#cc8ef5",
  "#8ce8c3",
  "#91d2fa",
  "#f5a524",
  "#e5484d",
  "#9fc7fa",
] as const;

/** Deterministic pseudo-random from the source, so particles never hydrate differently. */
function noise(a: number, b: number) {
  const raw = Math.sin(a * 12.9898 + b * 78.233) * 43758.5453;
  return raw - Math.floor(raw);
}

function dot(color: string, key: number) {
  return <i key={key} style={{ "--c": color } as CSSProperties} />;
}

/**
 * Two shapes from the original: "Bloom" opens a ring inside the heart and
 * flicks seven pairs of confetti out of it; "Firework" throws twelve sparks
 * upward. `fly` (0–1) is the Burst slider, normalised.
 */
export function LikeBurst({
  effect,
  fly,
}: {
  effect: BurstEffect;
  fly: number;
}) {
  if (effect === "Firework") {
    return (
      <>
        {Array.from({ length: 12 }, (_, index) => {
          const angle = -Math.PI / 2 + (index / 11 - 0.5) * Math.PI * 1.25;
          const distance = 22 + fly * 22 + noise(index, 7) * 10;

          return (
            <span
              key={index}
              className="like-fw"
              style={
                {
                  "--x": `${Math.cos(angle) * distance}px`,
                  "--d": `${noise(index, 8) * 60}ms`,
                } as CSSProperties
              }
            >
              <i
                style={
                  {
                    "--y": `${Math.sin(angle) * distance}px`,
                    background: PALETTE[index % PALETTE.length],
                  } as CSSProperties
                }
              />
            </span>
          );
        })}
      </>
    );
  }

  return (
    <>
      <span className="like-bloom" />
      {Array.from({ length: 7 }, (_, index) => (
        <span
          key={index}
          className="like-spoke"
          style={{ "--a": `${(360 / 7) * index - 90}deg` } as CSSProperties}
        >
          {dot(PALETTE[index % PALETTE.length], 0)}
          {dot(PALETTE[(index + 3) % PALETTE.length], 1)}
        </span>
      ))}
    </>
  );
}

