"use client";

import { useEffect, useRef, useState } from "react";

type Layer = { id: number; character: string };

/**
 * One wheel per decimal place. Only the wheels whose digit changed roll; the
 * outgoing and incoming glyphs travel in opposite directions (`up` = liking)
 * with a `place * 40ms` delay, so a carry reads right to left exactly like
 * Bencho's `popLayout` odometer.
 */
function Wheel({
  character,
  place,
  up,
  reduced,
}: {
  character: string;
  place: number;
  up: boolean;
  reduced: boolean;
}) {
  const [pair, setPair] = useState<{ current: Layer; previous: Layer | null }>(
    () => ({ current: { id: 0, character }, previous: null })
  );
  const last = useRef(character);

  // Render-phase adjustment: the new digit appears in the same paint as the
  // count change, with the old one stacked behind it for the exit roll.
  if (last.current !== character) {
    last.current = character;
    setPair((state) => ({
      current: { id: state.current.id + 1, character },
      previous: state.current,
    }));
  }

  useEffect(() => {
    const previous = pair.previous;
    if (!previous || reduced) return;

    const timer = window.setTimeout(
      () => {
        setPair((state) =>
          state.previous?.id === previous.id
            ? { ...state, previous: null }
            : state
        );
      },
      480 + place * 40
    );

    return () => window.clearTimeout(timer);
  }, [pair.previous, place, reduced]);

  const direction = up ? "up" : "down";

  return (
    <span className="relative inline-block h-[1.25em] overflow-hidden">
      {pair.previous && !reduced ? (
        <span
          key={pair.previous.id}
          className={`like-digit like-digit-out-${direction}`}
          style={{ animationDelay: `${place * 0.04}s` }}
        >
          {pair.previous.character}
        </span>
      ) : null}
      <span
        key={pair.current.id}
        className={
          pair.previous && !reduced
            ? `like-digit like-digit-in-${direction}`
            : "like-digit"
        }
        style={{ animationDelay: `${place * 0.04}s` }}
      >
        {pair.current.character}
      </span>
    </span>
  );
}

export function Odometer({ value, up }: { value: number; up: boolean }) {
  const [reduced, setReduced] = useState(false);
  const characters = value.toLocaleString("en-US").split("");

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(query.matches);
    sync();
    query.addEventListener("change", sync);
    return () => query.removeEventListener("change", sync);
  }, []);

  return (
    <span className="flex tabular-nums" aria-hidden="true">
      {characters.map((character, index) => {
        const place = characters.length - 1 - index;

        if (character === ",") {
          return (
            <span key={`comma-${place}`} className="leading-[1.25em]">
              ,
            </span>
          );
        }

        return (
          <Wheel
            key={`wheel-${place}`}
            character={character}
            place={place}
            up={up}
            reduced={reduced}
          />
        );
      })}
    </span>
  );
}

/**
 * Bencho's like sound, reconstructed from the `pop` and `tock` voice tables in
 * its sound engine: a short sine chirp going up when liking, and a low
 * triangle click when unliking.
 *
 * The AudioContext is created lazily inside the click handler, so it is born
 * from a user gesture and never touches `window` during render or module load.
 * No sound is played if the browser refuses to start audio.
 */

type Voice = {
  hz: number;
  to?: number;
  ms: number;
  gain: number;
  wave: OscillatorType;
  cut?: number;
  atk: number;
};

export type LikeSound = "pop" | "tock";

const VOICES: Record<LikeSound, readonly Voice[]> = {
  // 680 → 930 Hz, 34 ms, sine
  pop: [{ hz: 680, to: 930, ms: 34, gain: 0.05, wave: "sine", atk: 3 }],
  // 250 Hz, 28 ms, triangle through a 1.7 kHz lowpass
  tock: [{ hz: 250, ms: 28, gain: 0.045, wave: "triangle", cut: 1700, atk: 10 }],
};

let context: AudioContext | null = null;

function getContext(): AudioContext | null {
  if (typeof window === "undefined") return null;
  if (context) return context;

  const Ctor =
    window.AudioContext ??
    (window as unknown as { webkitAudioContext?: typeof AudioContext })
      .webkitAudioContext;
  if (!Ctor) return null;

  try {
    context = new Ctor();
  } catch {
    return null;
  }
  return context;
}

function emit(ctx: AudioContext, voice: Voice) {
  const start = ctx.currentTime;
  const duration = voice.ms / 1000;
  const attack = Math.min(voice.atk / 1000, duration * 0.6);

  const oscillator = ctx.createOscillator();
  oscillator.type = voice.wave;
  oscillator.frequency.setValueAtTime(voice.hz, start);
  if (voice.to) {
    oscillator.frequency.exponentialRampToValueAtTime(voice.to, start + duration);
  }

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(1e-4, start);
  gain.gain.exponentialRampToValueAtTime(voice.gain, start + attack);
  gain.gain.exponentialRampToValueAtTime(1e-4, start + duration);

  let tail: AudioNode = oscillator;
  if (voice.cut) {
    const filter = ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = voice.cut;
    oscillator.connect(filter);
    tail = filter;
  }

  tail.connect(gain);
  gain.connect(ctx.destination);

  oscillator.start(start);
  oscillator.stop(start + duration + 0.02);
}

export function playLikeSound(name: LikeSound) {
  const ctx = getContext();
  if (!ctx) return;

  // Safari can hand back a suspended context even inside a click; scheduling
  // at the frozen currentTime means the tone starts as soon as it resumes.
  if (ctx.state === "suspended") {
    void ctx.resume();
  }

  for (const voice of VOICES[name]) {
    emit(ctx, voice);
  }
}

