  --swp-muted: #929292;
  --swp-hover: rgba(255, 255, 255, 0.06);
  --swp-hover-strong: rgba(255, 255, 255, 0.2);
  --swp-flip: #2a2a2c;
}

.swp-stage .swp {
  position: relative;
  width: 300px;
  height: 235px;
  border-radius: var(--swp-r);
  overflow: hidden;
  color: var(--swp-on);
  font-family: inherit;
  letter-spacing: 0;
