  background: var(--swp-slab);
  box-shadow: inset 0 0 0 1px var(--swp-edge);
  opacity: 1;
  transition:
    top 500ms cubic-bezier(0.22, 1.12, 0.36, 1),
    height 500ms cubic-bezier(0.22, 1.12, 0.36, 1),
