  const roster = joined ? [...PEOPLE, YOU] : PEOPLE;
  const count = roster.length;

  return (
    <div className="flex w-full justify-center">
      <style>{HUDDLE_CSS}</style>

      <div className="w-full max-w-[340px] rounded-[28px] bg-[#f1f1f0] p-5 dark:bg-[#101010]">
