"use client";

import {
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
} from "react";
import {
  BAR_COUNT,
  GAP_MAX,
  formatNumber,
  generateSeries,
  layoutSeries,
  type Mode,
} from "./data";
import StackedPlot from "./plot";
import useReducedMotion from "./use-reduced-motion";

const cardWidth: CSSProperties = { width: 300 };

const MODES: Mode[] = ["Day", "Week"];

/**
 * Faithful port of Bencho's "Stacked bars" (Hover, Colour + 20 bars + 6px gap).
 *
 * Geometry, seeded data, palette, the 600 ms staggered bar transitions and the
 * 380/34 spring on the hover ring + tooltip follow the original. The plot is
 * scrubbed with the pointer; columns are also buttons, so keyboard focus
 * summons the same ring and tooltip. The tooltip doubles as the channel
 * legend — the block ships no separate legend.
 */
export default function Demo() {
  const [mode, setMode] = useState<Mode>("Day");
  const [active, setActive] = useState<number | null>(null);
  const [revealed, setRevealed] = useState(false);
  const reduced = useReducedMotion();

  const cardRef = useRef<HTMLDivElement>(null);
  const plotId = useId();

  useEffect(() => {
    const node = cardRef.current;
    if (!node) return;

    if (typeof IntersectionObserver === "undefined") {
      setRevealed(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setRevealed(true);
          observer.disconnect();
        }
      },
      { threshold: 0.3 }
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  const series = useMemo(() => generateSeries(mode, BAR_COUNT), [mode]);
  const layout = useMemo(
    () => layoutSeries(series, BAR_COUNT, GAP_MAX),
    [series]
  );

  function onTabKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
    event.preventDefault();
    const next: Mode = mode === "Day" ? "Week" : "Day";
    setMode(next);
    const tabs =
      event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="tab"]');
    tabs[next === "Week" ? 1 : 0]?.focus();
  }

  return (
    <div className="flex w-full justify-center py-6">
      <div
        ref={cardRef}
        className="relative flex select-none flex-col gap-4 rounded-[20px] bg-white p-4 text-[13px] text-[#17181a] ring-1 ring-black/[0.08] [--stb-slab:#ffffff] [--stb-mute:#8b8b8c] dark:bg-[#262626] dark:text-white dark:ring-white/[0.08] dark:[--stb-slab:#262626] dark:[--stb-mute:#979797]"
        style={cardWidth}
      >
        <div className="flex items-center gap-3">
          <div className="min-w-0 flex-1">
            <div className="text-[14px] font-medium leading-[18px] tracking-[-0.01em]">
              Traffic
            </div>
            <div className="text-[12px] leading-4 tabular-nums text-[#8b8b8c] dark:text-[#979797]">
              Last {BAR_COUNT} {mode === "Day" ? "days" : "weeks"}
            </div>
          </div>

          <div
            role="tablist"
            aria-label="Traffic range"
            onKeyDown={onTabKeyDown}
            className="relative grid grid-cols-2 rounded-[10px] bg-black/[0.06] p-0.5 dark:bg-white/[0.06]"
          >
            <span
              aria-hidden="true"
              className={`absolute bottom-0.5 left-0.5 top-0.5 w-[calc(50%-2px)] rounded-lg bg-[var(--stb-slab)] transition-transform duration-[220ms] ease-[cubic-bezier(0.22,1,0.36,1)] motion-reduce:transition-none ${
                mode === "Week" ? "translate-x-full" : ""
              }`}
            />
            {MODES.map((value) => {
              const selected = value === mode;
              return (
                <button
                  key={value}
                  type="button"
                  role="tab"
                  aria-selected={selected}
                  aria-controls={plotId}
                  tabIndex={selected ? 0 : -1}
                  onClick={() => {
                    if (value !== mode) setMode(value);
                  }}
                  className={`relative z-10 h-7 rounded-lg px-2.5 text-[12px] font-medium transition-[color,transform] duration-[160ms] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500/70 active:scale-[0.96] motion-reduce:transition-none ${
                    selected
                      ? "text-[#17181a] dark:text-white"
                      : "text-[#8b8b8c] hover:text-[#4b4c4d] dark:text-[#979797] dark:hover:text-[#c2c2c2]"
                  }`}
                >
                  {value}
                </button>
              );
            })}
          </div>
        </div>

        <div className="-mb-1 flex items-baseline gap-2" aria-live="polite">
          <span className="text-[30px] font-medium leading-8 tracking-[-0.03em] tabular-nums">
            {formatNumber(layout.total)}
          </span>
          <span className="text-[13px] text-[#8b8b8c] dark:text-[#979797]">
            visits
          </span>
        </div>

        <StackedPlot
          id={plotId}
          mode={mode}
          series={series}
          layout={layout}
          active={active}
          revealed={revealed}
          reduced={reduced}
          onActive={setActive}
        />

        <div className="-mt-2 flex justify-between text-[11px] leading-[14px] tabular-nums text-[#b3b3b4] dark:text-[#6b6b6b]">
          <span>{series[0].short}</span>
          <span>{series[BAR_COUNT - 1].short}</span>
        </div>
      </div>
    </div>
  );
}

/**
 * Data and geometry for the Stacked bars port.
 *
 * The series is generated by a seeded mulberry32 stream, exactly as the
 * original block does, so the shape is stable across renders and reloads
 * without shipping a hand-written table.
 */

export type Mode = "Day" | "Week";

export type Bar = {
  vals: number[];
  esc: number;
  label: string;
  short: string;
};

export const CATEGORIES = ["Direct", "Search", "Social", "Email"] as const;

export const BAR_COUNT = 20;
export const GAP_MAX = 6;

/** Card content box: 300px card − 16px padding on both sides. */
export const PLOT_W = 268;
export const PLOT_H = 127;
export const SEG_GAP = 2;
export const BASE_TOP = 104;
export const ESC_TOP = 107;
export const TIP_W = 132;

const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];

/** 2026-10-11, the fixed "today" the original seeds from. */
const TODAY = Date.UTC(2026, 9, 11);
const DAY = 86_400_000;

/** Palette from the block's `[data-colour="on"]` branch. */
export const SERIES_COLOURS = [
  "#9d7bf5",
  "#5b8def",
  "#9ab8db",
  "#f2c46d",
  "#74dcae",
  "#e57bb8",
] as const;

export const ALERT_COLOUR = "#e5484d";

/** mulberry32, matching the minified original bit for bit. */
function seeded(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 1831565813) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function labelDate(ms: number): string {
  const date = new Date(ms);
  return `${MONTHS[date.getUTCMonth()]} ${date.getUTCDate()}`;
}

const BASE = [520, 360, 210, 260];

export function generateSeries(mode: Mode, count: number): Bar[] {
  const random = seeded(mode === "Day" ? 4396 : 9117);
  const bars: Bar[] = [];

  for (let index = 0; index < 30; index++) {
    const offset = 29 - index;

    if (mode === "Day") {
      const time = TODAY - offset * DAY;
      const weekday = new Date(time).getUTCDay();
      const weekend = weekday === 0 || weekday === 6 ? 0.55 : 1;
      const spike = random() < 0.12 ? 1.5 : 1;
      const vals = BASE.map((base, segment) =>
        Math.round(
          base *
            weekend *
            (0.6 + random() * 0.8) *
            (segment === 3 ? spike * spike : spike)
        )
      );
      const esc = Math.round(3 + random() * 9 * weekend * spike);
      const label = labelDate(time);
      bars.push({ vals, esc, label, short: label });
    } else {
      const end = TODAY - offset * 7 * DAY;
      const start = end - 6 * DAY;
      const vals = BASE.map((base) =>
        Math.round(base * 5.6 * (0.75 + random() * 0.5))
      );
      const esc = Math.round(30 + random() * 44);
      const startDate = new Date(start);
      const endDate = new Date(end);
      const label =
        startDate.getUTCMonth() === endDate.getUTCMonth()
          ? `${labelDate(start)} – ${endDate.getUTCDate()}`
          : `${labelDate(start)} – ${labelDate(end)}`;
      bars.push({ vals, esc, label, short: labelDate(start) });
    }
  }

  return bars.slice(30 - count);
}

export type SegmentBox = { bottom: number; h: number };

export type LaidBar = {
  segs: SegmentBox[];
  top: number;
  esc: number;
};

export type Layout = {
  gap: number;
  colW: number;
  radius: number;
  bars: LaidBar[];
  totals: number[];
  total: number;
  maxTotal: number;
};

export function layoutSeries(
  series: Bar[],
  count: number,
  gapMax: number
): Layout {
  const gap = Math.max(1, Math.min(gapMax, (PLOT_W - 3 * count) / (count - 1)));
  const colW = (PLOT_W - gap * (count - 1)) / count;
  const radius = Math.min(2.5, colW / 2);

  const totals = series.map((bar) => bar.vals.reduce((a, b) => a + b, 0));
  const maxTotal = Math.max(...totals);
  const maxEsc = Math.max(...series.map((bar) => bar.esc));
  const scale = (100 - SEG_GAP * (CATEGORIES.length - 1)) / maxTotal;

  const bars = series.map((bar) => {
    let bottom = 0;
    const segs = bar.vals.map((value) => {
      const h = Math.max(2, value * scale);
      const box = { bottom, h };
      bottom += h + SEG_GAP;
      return box;
    });
    return {
      segs,
      top: bottom - SEG_GAP,
      esc: Math.max(3, (bar.esc / maxEsc) * 18),
    };
  });

  return {
    gap,
    colW,
    radius,
    bars,
    totals,
    total: totals.reduce((a, b) => a + b, 0),
    maxTotal,
  };
}

export function formatNumber(value: number): string {
  return Math.round(value).toLocaleString("en-US");
}

"use client";

import { useMemo, useRef, type KeyboardEvent, type PointerEvent } from "react";
import {
  ALERT_COLOUR,
  BAR_COUNT,
  BASE_TOP,
  CATEGORIES,
  ESC_TOP,
  PLOT_H,
  PLOT_W,
  SEG_GAP,
  SERIES_COLOURS,
  TIP_W,
  formatNumber,
  type Bar,
  type Layout,
  type Mode,
} from "./data";
import useSprings from "./spring";

const EASE = "cubic-bezier(0.22, 1, 0.36, 1)";

type PlotProps = {
  id: string;
  mode: Mode;
  series: Bar[];
  layout: Layout;
  active: number | null;
  revealed: boolean;
  reduced: boolean;
  onActive: (index: number | null) => void;
};

/**
 * The scrub area: stacked columns, hover ring and tooltip.
 *
 * Ring and tooltip are moved by a 380/34 spring; bars keep the block's own
 * 600 ms per-column staggered CSS transition. The pointer drives the whole
 * plot, while each column is a real button for keyboard users.
 */
export default function StackedPlot({
  id,
  mode,
  series,
  layout,
  active,
  revealed,
  reduced,
  onActive,
}: PlotProps) {
  const plotRef = useRef<HTMLDivElement>(null);

  const activeBar = active === null ? null : series[active];

  const topSegments = useMemo(() => {
    if (!activeBar) return [];
    return activeBar.vals
      .map((value, segment) => ({ value, segment }))
      .sort((a, b) => b.value - a.value)
      .slice(0, 2);
  }, [activeBar]);

  const geometry = useMemo(() => {
    const laid = active === null ? null : layout.bars[active];
    if (active === null || !laid) return null;
    const left = active * (layout.colW + layout.gap);
    const beside = left + layout.colW + 8;
    const tipX =
      beside + TIP_W <= PLOT_W || left - 8 - TIP_W < 0
        ? Math.min(136, beside)
        : left - 8 - TIP_W;

    return {
      x: left - 3,
      y: BASE_TOP - 2 - laid.top - 3,
      height: laid.top + SEG_GAP + 1 + SEG_GAP + laid.esc + 6,
      tip: tipX,
    };
  }, [active, layout]);

  // The original parks the ring and tooltip on their last position when the
  // pointer leaves; only opacity hides them.
  const parked = useRef({ x: 0, y: 0, height: 0, tip: 0 });
  if (geometry) parked.current = geometry;
  const springs = useSprings(parked.current, reduced);

  function scrub(event: PointerEvent<HTMLDivElement>) {
    const rect = plotRef.current?.getBoundingClientRect();
    if (!rect || rect.width === 0) return;
    const index = Math.floor(
      ((event.clientX - rect.left) / rect.width) * BAR_COUNT
    );
    onActive(Math.max(0, Math.min(BAR_COUNT - 1, index)));
  }

  function onPointerDown(event: PointerEvent<HTMLDivElement>) {
    try {
      event.currentTarget.setPointerCapture(event.pointerId);
    } catch {
      // Pointer capture is best-effort (older Safari, synthetic pointers).
    }
    scrub(event);
  }

  function onPointerUp(event: PointerEvent<HTMLDivElement>) {
    try {
      event.currentTarget.releasePointerCapture(event.pointerId);
    } catch {
      // Already released or never captured.
    }
    if (event.pointerType !== "mouse") onActive(null);
  }

  function onBarKeyDown(event: KeyboardEvent<HTMLButtonElement>) {
    if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
    event.preventDefault();
    const step = event.key === "ArrowRight" ? 1 : -1;
    const next = Math.max(0, Math.min(BAR_COUNT - 1, (active ?? 0) + step));
    const columns =
      event.currentTarget.parentElement?.querySelectorAll<HTMLButtonElement>(
        "[data-bar]"
      );
    columns?.[next]?.focus();
  }

  const barTransition = (index: number) =>
    reduced
      ? "none"
      : `height 600ms ${EASE} ${index * 14}ms, bottom 600ms ${EASE} ${
          index * 14
        }ms, background-color 160ms ease`;

  return (
    <div
      ref={plotRef}
      id={id}
      role="tabpanel"
      aria-label={`Traffic by ${mode === "Day" ? "day" : "week"}, stacked by channel`}
      className="relative cursor-crosshair touch-none"
      style={{ height: PLOT_H }}
      onPointerDown={onPointerDown}
      onPointerMove={scrub}
      onPointerUp={onPointerUp}
      onPointerCancel={() => onActive(null)}
      onPointerLeave={() => onActive(null)}
    >
      <span
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-0 z-0 h-px bg-black/[0.12] dark:bg-white/[0.12]"
        style={{ top: BASE_TOP }}
      />

      {series.map((bar, index) => {
        const laid = layout.bars[index];
        const dimmed = active !== null && active !== index;
        const summary = CATEGORIES.map(
          (name, segment) => `${name} ${formatNumber(bar.vals[segment])}`
        ).join(", ");

        return (
          <button
            key={index}
            type="button"
            data-bar=""
            aria-label={`${bar.label}: ${formatNumber(
              layout.totals[index]
            )} visits. ${summary}. Bounced ${bar.esc}.`}
            onFocus={() => onActive(index)}
            onBlur={() => onActive(null)}
            onKeyDown={onBarKeyDown}
            className="absolute inset-y-0 z-10 cursor-crosshair bg-transparent p-0 focus:outline-none focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-500"
            style={{
              left: index * (layout.colW + layout.gap),
              width:
                index === BAR_COUNT - 1
                  ? layout.colW
                  : layout.colW + layout.gap,
              borderRadius: layout.radius + 3,
            }}
          >
            {laid.segs.map((segment, segmentIndex) => {
              const colour = SERIES_COLOURS[segmentIndex];
              return (
                <span
                  key={segmentIndex}
                  aria-hidden="true"
                  className="absolute left-0 block"
                  style={{
                    width: layout.colW,
                    bottom: 25 + (revealed ? segment.bottom : 0),
                    height: revealed ? segment.h : 0,
