type IslandProps = {
  activity: Activity;
  bounce: number;
  tone: Tone;
  startOpen?: boolean;
};

/**
 * A 1:1 port of Bencho's "Dynamic island" block.
 *
 * One black pill holds a live activity. Pressing it springs width, height and
 * corner radius from 150 × 36 to the activity's card with 380 / (34 − 16b)
 * over mass 0.9, and the compact row crossfades into the card through blur and
 * scale. Timer pauses in place, the call can be hung up, the flight bar creeps
 * towards Edmonton, and the track pauses. All four activities share the same
 * second-by-second tick.
 *
 * The source's Web Audio cues and framer-motion are not ported: the spring is
 * integrated locally, and the album/portrait photos are replaced with local
 * CSS artwork. Press feedback (0.97 while held), geometry, copy, colours and
 * the reduced-motion behaviour are kept.
 */
export default function DynamicIsland({
  activity,
  bounce,
  tone,
  startOpen = true,
}: IslandProps) {
  const reduced = useReducedMotion();
  const kind: Activity = ACTIVITIES.includes(activity) ? activity : "Timer";

  const [open, setOpen] = useState(startOpen);
  const [pressed, setPressed] = useState(false);
  const [pop, setPop] = useState(0);

  const [data, setData] = useState<IslandData>({
    left: 299,
    talk: 42,
    at: 71,
    flown: 24,
    paused: false,
    playing: true,
  });

  /** Bumped only when the activity is changed from outside the pill. */
  const popScale = useContentPop(pop, reduced);
  const previousActivity = useRef(activity);

  useEffect(() => {
    // Pop the content shell every time the activity prop changes, like the
    // source's `l` counter; the initial mount stays still.
    if (previousActivity.current === activity) return;
    previousActivity.current = activity;
    setPop((value) => value + 1);
  }, [activity]);

  useEffect(() => {
    const timer = window.setInterval(() => {
      setData((current) => ({
        ...current,
        left: current.paused
          ? current.left
          : current.left <= 0
            ? 299
            : current.left - 1,
        talk: current.talk + 1,
        at: current.playing
          ? current.at >= TRACK_TOTAL
            ? 0
            : current.at + 1
          : current.at,
        flown: current.flown >= FLIGHT_TOTAL ? 0 : current.flown + 1,
      }));
    }, 1000);
    return () => window.clearInterval(timer);
  }, []);

  const shape = open ? OPEN[kind] : COMPACT;
  const clampedBounce = Math.min(100, Math.max(0, bounce)) / 100;

  const targets = useMemo(
    () => ({
      width: shape.width,
      height: shape.height,
      radius: shape.radius,
      scale: reduced ? 1 : pressed ? 0.97 : 1,
    }),
    [shape.width, shape.height, shape.radius, pressed, reduced],
  );

  const config = useMemo(
    () => ({ stiffness: 380, damping: 34 - clampedBounce * 16, mass: 0.9 }),
    [clampedBounce],
  );

  const geometry = useSpringVector(targets, config, reduced);

  /** Two-layer content swap: the old row fades out while the new one arrives. */
  const layerKey = `${kind}-${open}`;
  const [tracked, setTracked] = useState({ key: layerKey, kind, open });
  const [animated, setAnimated] = useState(false);
  const [leaving, setLeaving] = useState<{
    key: string;
    kind: Activity;
    open: boolean;
  } | null>(null);

  if (tracked.key !== layerKey) {
    setLeaving(tracked);
    setTracked({ key: layerKey, kind, open });
    setAnimated(true);
  }

  useEffect(() => {
    if (!leaving) return;
    const timer = window.setTimeout(
      () => setLeaving(null),
      reduced ? 0 : 220,
    );
    return () => window.clearTimeout(timer);
  }, [leaving, reduced]);

  const setPaused = () =>
    setData((current) => ({ ...current, paused: !current.paused }));
  const setPlaying = () =>
    setData((current) => ({ ...current, playing: !current.playing }));
  const close = () => setOpen(false);

  const announcement = !open
    ? `${kind} island closed.`
    : kind === "Timer"
      ? `Timer island open. ${data.paused ? "Timer paused." : "Timer running."}`
      : kind === "Call"
        ? "Call island open. Mara is on a call."
        : kind === "Music"
          ? `Music island open. Soft Focus by Lumen Park. ${data.playing ? "Playing." : "Paused."}`
          : `Flight island open. SFO to YEG.`;

  const radius = geometry.radius;

  return (
    <div
      className="dyn mx-auto"
      data-reduced={reduced ? "true" : undefined}
    >
      <style>{DYNAMIC_ISLAND_CSS}</style>

      <div className="dyn-top">
        <div
          className="dyn-pill"
          data-tone={tone === "White" ? "white" : undefined}
          style={{
            width: geometry.width,
            height: geometry.height,
            borderRadius: radius,
            transform: `scale(${geometry.scale})`,
          }}
          onPointerDown={() => {
            if (!reduced) setPressed(true);
          }}
          onPointerUp={() => setPressed(false)}
          onPointerLeave={() => setPressed(false)}
          onPointerCancel={() => setPressed(false)}
        >
          <button
            type="button"
            className="dyn-toggle"
            aria-expanded={open}
            aria-label={open ? `Close ${kind}` : `Open ${kind}`}
            style={{ borderRadius: radius }}
            onClick={() => setOpen((value) => !value)}
          />

          <div
            className="dyn-in"
            style={{ transform: `scale(${popScale})` }}
          >
            {leaving && !reduced ? (
              <div
                key={leaving.key}
                className="dyn-layer dyn-exit"
                aria-hidden="true"
              >
                <Panel
                  kind={leaving.kind}
                  open={leaving.open}
                  data={data}
                  inert
                  onPause={setPaused}
                  onPlay={setPlaying}
                  onEnd={close}
                />
              </div>
            ) : null}

            <div
              key={layerKey}
              className={`dyn-layer${animated ? " dyn-enter" : ""}`}
            >
              <Panel
                kind={kind}
                open={open}
                data={data}
                onPause={setPaused}
                onPlay={setPlaying}
                onEnd={close}
              />
            </div>
          </div>
        </div>
      </div>

      <p className="sr-only" aria-live="polite" aria-atomic="true">
        {announcement}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

/**
 * The two springs Bencho uses inside the island. The shape spring is the one
 * framer-motion is given for width, height, corner radius and the press scale;
 * the content spring only rolls the compact row or card back from 1.08 after
 * the activity changes from outside.
 */
export type SpringConfig = { stiffness: number; damping: number; mass: number };

/** Integration step; one frame is split into steps no longer than this. */
const STEP = 1 / 240;

/**
 * Integrates a set of numeric properties towards `target` with one shared
 * spring, so width, height and radius arrive together instead of one corner
 * trailing the other. `target` is expected to be memoised by the caller.
 */
export function useSpringVector<T extends Record<string, number>>(
  target: T,
  config: SpringConfig,
  reduced: boolean,
): T {
  const [values, setValues] = useState<T>(target);
  const position = useRef<Record<string, number>>({ ...target });
  const velocity = useRef<Record<string, number>>(
    Object.fromEntries(Object.keys(target).map((key) => [key, 0])),
  );

  useEffect(() => {
    if (reduced) {
      position.current = { ...target };
      setValues({ ...target });
      return;
    }

    const keys = Object.keys(target);
    const { stiffness, damping, mass } = config;
    let frame = 0;
    let previous = 0;

    const tick = (now: number) => {
      const elapsed = previous
        ? Math.min((now - previous) / 1000, 1 / 30)
        : STEP;
      previous = now;

      const steps = Math.max(1, Math.ceil(elapsed / STEP));
      const dt = elapsed / steps;

      for (let step = 0; step < steps; step += 1) {
        for (const key of keys) {
          const offset = position.current[key] - target[key];
          velocity.current[key] +=
            ((-stiffness * offset - damping * velocity.current[key]) / mass) *
            dt;
          position.current[key] += velocity.current[key] * dt;
        }
      }

      let settled = true;
      for (const key of keys) {
        if (
          Math.abs(position.current[key] - target[key]) > 0.01 ||
          Math.abs(velocity.current[key]) > 0.01
        ) {
          settled = false;
          break;
        }
      }

      if (settled) {
        position.current = { ...target };
        velocity.current = Object.fromEntries(keys.map((key) => [key, 0]));
      }

      setValues({ ...position.current } as T);
      if (!settled) frame = requestAnimationFrame(tick);
    };

    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [target, config, reduced]);

  return values;
}

/**
 * `dyn-in` scale: whenever the activity is changed from the control row the
 * content shell is nudged to 1.08 and springs back with 500 / 18. The first
 * render is skipped so the island does not pop on mount.
 */
export function useContentPop(pop: number, reduced: boolean): number {
  const [scale, setScale] = useState(1);
  const position = useRef(1);
  const velocity = useRef(0);
  const lastPop = useRef(pop);

  useEffect(() => {
    if (reduced) {
      setScale(1);
      return;
    }

    if (lastPop.current === pop) return;
    lastPop.current = pop;

    position.current = 1.08;
    velocity.current = 0;
    setScale(1.08);

    let frame = 0;
    let previous = 0;

    const tick = (now: number) => {
      const elapsed = previous
        ? Math.min((now - previous) / 1000, 1 / 30)
        : STEP;
      previous = now;

      const steps = Math.max(1, Math.ceil(elapsed / STEP));
      const dt = elapsed / steps;

      for (let step = 0; step < steps; step += 1) {
        const offset = position.current - 1;
        velocity.current += (-500 * offset - 18 * velocity.current) * dt;
        position.current += velocity.current * dt;
      }

      const settled =
        Math.abs(position.current - 1) < 0.0005 &&
        Math.abs(velocity.current) < 0.0005;
      if (settled) {
        position.current = 1;
        velocity.current = 0;
      }

      setScale(settled ? 1 : position.current);
      if (!settled) frame = requestAnimationFrame(tick);
    };

    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [pop, reduced]);

  return scale;
}

/** Mirrors the media query into React; no browser API runs during render. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(query.matches);
    sync();
    query.addEventListener("change", sync);
    return () => query.removeEventListener("change", sync);
  }, []);

  return reduced;
}

/**
