"use client";

import {
  type CSSProperties,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

/* The block's fixed geometry, unchanged. The notch is measured from the
   rendered label so the gap follows the word, and the SVG stroke sits half a
   stroke inside the box so rounding cannot clip it. */
const W = 280;
const H = 52;
const SCALE = 0.78;
const IN = 0.75;

/* Measure before paint in the browser, without tripping the SSR warning. */
const useSafeLayoutEffect =
  typeof window === "undefined" ? useEffect : useLayoutEffect;

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

export type LabelInputField = "Email" | "Password";

type LabelInputProps = {
  field: LabelInputField;
  corner: number;
  value: string;
  onChange: (value: string) => void;
  onFocus?: () => void;
  onBlur: () => void;
  show?: boolean;
  onToggleShow?: () => void;
  invalid?: boolean;
  describedBy?: string;
  maxLength?: number;
};

export default function LabelInput({
  field,
  corner,
  value,
  onChange,
  onFocus,
  onBlur,
  show = false,
  onToggleShow,
  invalid = false,
  describedBy,
  maxLength,
}: LabelInputProps) {
  const id = `lbi-${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const secret = field === "Password";
  const label = secret ? "Password" : "Email";

  const [focus, setFocus] = useState(false);
  const labelRef = useRef<HTMLLabelElement>(null);
  const [labelWidth, setLabelWidth] = useState(40);

  useSafeLayoutEffect(() => {
    const node = labelRef.current;
    if (!node) return;

    /* The notch follows the rendered word, so remeasure if the web font
       swaps in after the first layout. */
    setLabelWidth(node.offsetWidth);
    if (typeof ResizeObserver === "undefined") return;

    const observer = new ResizeObserver(() => setLabelWidth(node.offsetWidth));
    observer.observe(node);
    return () => observer.disconnect();
  }, [label]);

  const radius = clamp(corner, 0, H / 2);
  const up = focus || value.length > 0;

  /* Never start the notch inside the corner curve: the gap has to open on
     the straight part of the top edge. */
  const lx = Math.max(14, radius + 4);
  const x0 = Math.max(radius * 0.6, lx - 5);
  const x1 = lx + labelWidth * SCALE + 5;
  const a = radius - IN;
  const R = W - IN;
  const B = H - IN;
  const mid = W / 2;

  const notchMid = (x0 + x1) / 2;
  const gapLeft = `M${notchMid},${IN} L${x0},${IN}`;
  const gapRight = `M${notchMid},${IN} L${x1},${IN}`;

  const right =
    radius > 0
      ? `M${x1},${IN} L${W - radius},${IN} A${a},${a} 0 0 1 ${R},${radius} L${R},${H - radius} A${a},${a} 0 0 1 ${W - radius},${B} L${mid},${B}`
      : `M${x1},${IN} L${R},${IN} L${R},${B} L${mid},${B}`;

  const left =
    radius > 0
      ? `M${x0},${IN} L${radius},${IN} A${a},${a} 0 0 0 ${IN},${radius} L${IN},${H - radius} A${a},${a} 0 0 0 ${radius},${B} L${mid},${B}`
      : `M${x0},${IN} L${IN},${IN} L${IN},${B} L${mid},${B}`;

  const [flip, setFlip] = useState(0);

  const reveal = () => {
    setFlip((current) => current + 1);
    onToggleShow?.();
  };

  return (
    <div
      className="lbi"
      data-up={up ? "true" : "false"}
      data-focus={focus ? "true" : "false"}
      data-filled={value.length > 0 ? "true" : "false"}
    >
      <div
        className="lbi-box"
        style={
          {
            width: W,
            height: H,
            borderRadius: radius,
            "--lbi-x": `${lx}px`,
          } as CSSProperties
        }
      >
        <svg
          className="lbi-ring"
          width={W}
          height={H}
          viewBox={`0 0 ${W} ${H}`}
          aria-hidden="true"
          focusable="false"
        >
          <path d={right} />
          <path d={left} />
          <path className="lbi-gap" d={gapLeft} pathLength={1} />
          <path className="lbi-gap" d={gapRight} pathLength={1} />
        </svg>

        <label className="lbi-label" htmlFor={id} ref={labelRef}>
          {[...label].map((character, index) => (
            <span
              key={`${character}-${index}`}
              style={{ "--i": index } as CSSProperties}
            >
              {character}
            </span>
          ))}
        </label>

        <input
          id={id}
          className="lbi-field"
          data-flip={flip % 2}
          type={secret && !show ? "password" : secret ? "text" : "email"}
          autoCapitalize="off"
          autoCorrect="off"
          autoComplete="off"
          spellCheck={false}
          maxLength={maxLength}
          value={value}
          aria-invalid={invalid || undefined}
          aria-describedby={describedBy}
          onChange={(event) => onChange(event.target.value)}
          onFocus={() => {
            setFocus(true);
            onFocus?.();
          }}
          onBlur={() => {
            setFocus(false);
            onBlur();
          }}
          style={{ paddingRight: secret ? 48 : lx }}
        />

        {secret ? (
          <button
            className="lbi-eye"
            type="button"
            data-show={show ? "true" : "false"}
            aria-label={show ? "Hide password" : "Show password"}
            onPointerDown={(event) => event.preventDefault()}
            onClick={reveal}
          >
            <svg
              width="16"
              height="16"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden="true"
            >
              <path d="M2.062 12.348a1 1 0 0 1 0-.696 10.75 10.75 0 0 1 19.876 0 1 1 0 0 1 0 .696 10.75 10.75 0 0 1-19.876 0" />
              <circle cx="12" cy="12" r="3" />
            </svg>
            <svg
              width="16"
              height="16"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden="true"
            >
              <path d="M10.733 5.076a10.744 10.744 0 0 1 11.205 6.575 1 1 0 0 1 0 .696 10.747 10.747 0 0 1-1.444 2.49" />
              <path d="M14.084 14.158a3 3 0 0 1-4.242-4.242" />
              <path d="M17.479 17.499a10.75 10.75 0 0 1-15.417-5.151 1 1 0 0 1 0-.696 10.75 10.75 0 0 1 4.446-5.143" />
              <path d="m2 2 20 20" />
            </svg>
          </button>
        ) : null}
      </div>
    </div>
  );
}

components/input/one-time-code.code:
"use client";

import { useState } from "react";
import Otp from "./otp";

type Answer = "Accept" | "Reject";

const SEGMENT =
  "inline-flex min-h-8 items-center justify-center rounded-full px-3 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-400/60 focus-visible:ring-offset-1 focus-visible:ring-offset-zinc-100 dark:focus-visible:ring-offset-zinc-900";
const ACTIVE =
  "bg-white text-zinc-900 shadow-sm dark:bg-[#262626] dark:text-white";
const IDLE =
  "text-zinc-500 hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-white";

/**
 * Gallery shell for the OTP block. Bencho exposes length, answer and corner;
 * the two segmented controls make the 4/6 layout and the rejection path
 * reachable, while the block itself keeps its default 12 px corner.
 */
export default function Demo() {
  const [length, setLength] = useState<4 | 6>(4);
  const [answer, setAnswer] = useState<Answer>("Accept");

  return (
    <div className="flex w-full flex-col items-center">
      <Otp length={length} answer={answer} corner={12} />

      <div className="mt-1 flex flex-wrap items-center justify-center gap-x-5 gap-y-2">
        <div
          role="group"
          aria-label="Code length"
          className="flex items-center gap-2"
        >
          <span className="text-[10px] font-medium uppercase tracking-[0.14em] text-zinc-400 dark:text-zinc-500">
            Digits
          </span>
          <div className="flex rounded-full bg-zinc-100 p-0.5 dark:bg-zinc-900">
            {([4, 6] as const).map((value) => (
              <button
                key={value}
                type="button"
                aria-pressed={length === value}
                onClick={() => setLength(value)}
                className={`${SEGMENT} ${length === value ? ACTIVE : IDLE}`}
              >
                {value}
              </button>
            ))}
          </div>
        </div>

        <div
          role="group"
          aria-label="Answer"
          className="flex items-center gap-2"
        >
          <span className="text-[10px] font-medium uppercase tracking-[0.14em] text-zinc-400 dark:text-zinc-500">
            Answer
          </span>
          <div className="flex rounded-full bg-zinc-100 p-0.5 dark:bg-zinc-900">
            {(["Accept", "Reject"] as const).map((value) => (
              <button
                key={value}
                type="button"
                aria-pressed={answer === value}
                onClick={() => setAnswer(value)}
                className={`${SEGMENT} ${answer === value ? ACTIVE : IDLE}`}
              >
                {value}
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * Geometry and motion shared by the OTP port, lifted from Bencho's
 * `Otp-BDyim0GA.js`:
 *
 *   p = 36   cell width     m = 44   row height
 *   ee = 7   gap            h = 128  capsule width
 *   l = 260  digit entrance  _ = 620  rejection shake
 *
 * The cells sit on a 43 px pitch (36 + 7). Everything is expressed in plain
 * numbers so the render pass stays deterministic and SSR-safe.
 */

export const CELL = 36;
export const ROW_HEIGHT = 44;
export const GAP = 7;
export const PITCH = CELL + GAP;
export const CAPSULE = 128;
export const ENTER_MS = 260;
export const DENY_MS = 620;
export const DENY_SETTLE_MS = 820;

/** The success blob is a soft spring: k .075, d = 1 - .84 * sqrt(k). */
export const SUCCESS_SPRING = {
  k: 0.075,
  d: 1 - 0.84 * Math.sqrt(0.075),
};

/** The caret is a stiffer spring; the original inlines 0.2 / 0.62. */
export const CARET_SPRING = { k: 0.2, d: 0.62 };

export type Spring = { x: number; v: number };

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

export function mix(from: number, to: number, t: number) {
  return from + (to - from) * t;
}

/** Hermite ease, `smoothstep(edge0, edge1, x)`. */
export function smooth(edge0: number, edge1: number, x: number) {
  const t = clamp((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

export function rowWidth(length: number) {
  return length * CELL + (length - 1) * GAP;
}

/** Where a cell rests when the row is complete, before fusing to the centre. */
export function cellX(index: number) {
  return index * PITCH;
}

export function fusedCellX(length: number) {
  return (rowWidth(length) - CELL) / 2;
}

/** The caret parks in the centre of the next empty cell, clamped to the last. */
export function caretX(codeLength: number, length: number) {
  return Math.min(codeLength, length - 1) * PITCH + CELL / 2;
}

/**
 * Advance a spring one animation frame and report whether it is still moving.
 * `epsilon` is the original's settle threshold (0.05 px for the caret,
 * 0.0008 for the success blob).
 */
export function stepSpring(
  spring: Spring,
  target: number,
  config: { k: number; d: number },
  rate: number,
  epsilon = 0.05,
) {
  spring.v += (target - spring.x) * config.k * rate;
  spring.v *= config.d ** rate;
  spring.x += spring.v * rate;

  if (Math.abs(target - spring.x) < epsilon && Math.abs(spring.v) < epsilon) {
    spring.x = target;
    spring.v = 0;
    return false;
  }

  return true;
}

/** Decaying sideways wave; the phase offset runs down the row. */
export function denyOffset(index: number, elapsed: number) {
  return (
    5 *
    Math.exp(-elapsed / 190) *
    Math.sin((elapsed / 1000) * Math.PI * 2 * 10 + index * 0.55)
  );
}

/** Digits drop out right to left, eight pixels each. */
export function denyFall(index: number, length: number, elapsed: number) {
  const t = smooth(0, 1, (elapsed - 300 - (length - 1 - index) * 45) / 220);
  return { shift: t * 8, opacity: 1 - t };
}

/** A freshly typed digit overshoots by 4% over 260 ms. */
export function arrivalScale(startedAt: number | undefined, now: number) {
  if (startedAt === undefined) return 1;
  const t = (now - startedAt) / ENTER_MS;
  return t > 0 && t < 1 ? 1 + 0.04 * Math.sin(Math.PI * t) : 1;
}

/** While checking, a 900 ms pulse travels across every box. */
export function checkScale(index: number, length: number, now: number) {
  const t = ((now % 900) / 900) * (length + 2) - index;
  return 1 - 0.07 * (t > 0 && t < 2 ? Math.sin((t / 2) * Math.PI) : 0);
}

/**
 * Bencho's `.otp-*` layer, scoped under `.otp-demo`. Only the pieces Tailwind
 * cannot express live here: the goo filter hooks, the digit entrance, the
 * breathing caret and the focus ring on the invisible field. Colours are the
 * resolved `--fill-slab` / `--fill-on` values from `index-0e0OZHzj.css`:
 * light #fff on #f7f7f6, dark #262626 on #0a0a0a.
 */
export const OTP_CSS = `
