export type Suggestion = {
  id: string;
  title: string;
  meta: string;
};

/**
 * Local corpus for the search demo. Keeping it in the item folder means the
 * block still works with no network and no project imports, while the list is
 * long enough to show filtering, wrapping and the scroll container.
 */
export const SUGGESTIONS: readonly Suggestion[] = [
  { id: "motion", title: "Motion", meta: "Foundations · 8 min" },
  { id: "tokens", title: "Design tokens", meta: "Foundations · 5 min" },
  { id: "dark-mode", title: "Dark mode", meta: "Guides · 4 min" },
  { id: "shortcuts", title: "Keyboard shortcuts", meta: "Guides · 3 min" },
  { id: "command-menu", title: "Command menu", meta: "Components · 6 min" },
  { id: "search-field", title: "Search field", meta: "Components · 5 min" },
  { id: "reduced-motion", title: "Reduced motion", meta: "Accessibility · 3 min" },
  { id: "focus-states", title: "Focus states", meta: "Accessibility · 4 min" },
] as const;

export function filterSuggestions(query: string): Suggestion[] {
  const needle = query.trim().toLowerCase();
  if (!needle) return [...SUGGESTIONS];

  return SUGGESTIONS.filter((item) =>
    `${item.title} ${item.meta}`.toLowerCase().includes(needle),
  );
}

/**
 * Bencho's Seek cues, rebuilt from the `expand`, `off` and `click` voice
 * tables in its sound engine, plus the tonal half of its `select` cue. The
 * AudioContext is created lazily inside the gesture that needs it.
 */

type Voice = {
  hz: number;
  to?: number;
  ms: number;
  gain: number;
  wave: OscillatorType;
  cut?: number;
  atk: number;
  /** Delay before the voice starts, in milliseconds. */
  at?: number;
};

export type SearchSound = "expand" | "off" | "click" | "select";

const VOICES: Record<SearchSound, readonly Voice[]> = {
  // Two sines: 196 → 174 Hz, and a quiet 294 → 262 Hz a beat later
  expand: [
    { hz: 196, to: 174, ms: 360, gain: 0.042, wave: "sine", cut: 880, atk: 36 },
    {
      hz: 294,
      to: 262,
      ms: 300,
      gain: 0.014,
      wave: "sine",
      cut: 1100,
      atk: 48,
      at: 24,
    },
  ],
  // 330 → 247 Hz, 88 ms sine through a 720 Hz lowpass
  off: [{ hz: 330, to: 247, ms: 88, gain: 0.03, wave: "sine", cut: 720, atk: 8 }],
  // 196 → 130 Hz, 150 ms sine through a 900 Hz lowpass
  click: [{ hz: 196, to: 130, ms: 150, gain: 0.07, wave: "sine", cut: 900, atk: 6 }],
  // The tonal part of Bencho's `select`: 664 → 415 Hz over 20 ms
  select: [
    { hz: 664, to: 415, ms: 20, gain: 0.024, wave: "sine", atk: 1 },
  ],
};

let context: AudioContext | null = null;

function getContext(): AudioContext | null {
  if (typeof window === "undefined") return null;
  if (context) return context;

  const Ctor =
    window.AudioContext ??
    (window as unknown as { webkitAudioContext?: typeof AudioContext })
      .webkitAudioContext;
  if (!Ctor) return null;

  try {
    context = new Ctor();
  } catch {
    return null;
  }
  return context;
}

function emit(ctx: AudioContext, voice: Voice) {
  const start = ctx.currentTime + (voice.at ?? 0) / 1000;
  const duration = voice.ms / 1000;
  const attack = Math.min(voice.atk / 1000, duration * 0.6);

  const oscillator = ctx.createOscillator();
  oscillator.type = voice.wave;
  oscillator.frequency.setValueAtTime(voice.hz, start);
  if (voice.to) {
    oscillator.frequency.exponentialRampToValueAtTime(voice.to, start + duration);
  }

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(1e-4, start);
  gain.gain.exponentialRampToValueAtTime(voice.gain, start + attack);
  gain.gain.exponentialRampToValueAtTime(1e-4, start + duration);

  let tail: AudioNode = oscillator;
  if (voice.cut) {
    const filter = ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = voice.cut;
    oscillator.connect(filter);
    tail = filter;
  }

  tail.connect(gain);
  gain.connect(ctx.destination);

  oscillator.start(start);
  oscillator.stop(start + duration + 0.02);
}

export function playSearchSound(name: SearchSound) {
  const ctx = getContext();
  if (!ctx) return;

  // Safari can return a suspended context even inside a gesture; scheduling at
  // the frozen currentTime means the tone starts as soon as it resumes.
  if (ctx.state === "suspended") {
    void ctx.resume();
  }

  for (const voice of VOICES[name]) {
    emit(ctx, voice);
  }
}

"use client";

import { useEffect, useRef } from "react";
import type { Suggestion } from "./search-data";

type SuggestionListProps = {
  id: string;
  query: string;
  matches: Suggestion[];
  active: number;
  width: number;
  optionId: (id: string) => string;
  onActive: (index: number) => void;
  onChoose: (item: Suggestion) => void;
};

function Match({ text, query }: { text: string; query: string }) {
  const needle = query.trim();
  const at = needle
    ? text.toLowerCase().indexOf(needle.toLowerCase())
    : -1;

  if (at < 0) return <>{text}</>;

  return (
    <>
      {text.slice(0, at)}
      <mark className="rounded-[2px] bg-[#17181a]/10 px-px text-inherit dark:bg-white/15">
        {text.slice(at, at + needle.length)}
      </mark>
      {text.slice(at + needle.length)}
    </>
  );
}

/**
 * The gallery extension around Bencho's field: a local result corpus, matched
 * text highlighted in place, and a scroll container that keeps the active
 * option visible without moving the page.
 */
export default function SuggestionList({
  id,
  query,
  matches,
  active,
  width,
  optionId,
  onActive,
  onChoose,
}: SuggestionListProps) {
  const listRef = useRef<HTMLUListElement>(null);
  const optionRefs = useRef<Array<HTMLLIElement | null>>([]);

  useEffect(() => {
    const list = listRef.current;
    const option = optionRefs.current[active];
    if (!list || !option) return;

    const top = option.offsetTop;
    const bottom = top + option.offsetHeight;
    if (top < list.scrollTop) list.scrollTop = top;
    else if (bottom > list.scrollTop + list.clientHeight) {
      list.scrollTop = bottom - list.clientHeight;
    }
  }, [active, matches.length]);

  const trimmed = query.trim();
  const empty = matches.length === 0;

  return (
    <div
      className="seek-panel absolute left-1/2 top-[76px] z-20 -translate-x-1/2"
      style={{ width }}
    >
      <div className="overflow-hidden rounded-2xl border border-[#17181a]/10 bg-white shadow-[0_12px_32px_-12px_rgba(23,24,26,0.28)] dark:border-white/10 dark:bg-[#1a1a1a] dark:shadow-[0_16px_40px_-12px_rgba(0,0,0,0.7)]">
        <div className="flex items-baseline justify-between gap-3 border-b border-[#17181a]/[0.06] px-3.5 py-2.5 dark:border-white/[0.08]">
          <span className="text-[10px] font-medium uppercase tracking-[0.14em] text-[#85847e] dark:text-[#828282]">
            {trimmed ? "Results" : "Suggestions"}
          </span>
          <span className="text-[10px] tabular-nums text-[#85847e] dark:text-[#828282]">
            {matches.length}
          </span>
        </div>

        <ul
          ref={listRef}
          id={id}
          role="listbox"
          aria-label="Search results"
          className="max-h-[208px] overflow-y-auto overscroll-contain p-1.5"
        >
          {empty ? (
            <li
              role="option"
              aria-disabled="true"
              aria-selected="false"
              className="flex cursor-default flex-col gap-1 rounded-xl px-3 py-5 text-center"
            >
              <span className="text-[13px] font-medium text-[#17181a] dark:text-white">
                No matches for “{trimmed}”
              </span>
              <span className="text-[11px] text-[#85847e] dark:text-[#828282]">
                Press Enter to search anyway
              </span>
            </li>
          ) : (
            matches.map((item, index) => (
              <li
                key={item.id}
                ref={(element) => {
                  optionRefs.current[index] = element;
                }}
                id={optionId(item.id)}
                role="option"
                aria-selected={index === active}
                tabIndex={-1}
                onMouseDown={(event) => event.preventDefault()}
                onMouseEnter={() => onActive(index)}
                onClick={() => onChoose(item)}
                className={`flex cursor-pointer items-center justify-between gap-3 rounded-xl px-3 py-2 transition-colors duration-100 ${
                  index === active
                    ? "bg-[#17181a]/[0.055] dark:bg-white/[0.08]"
                    : "bg-transparent"
                }`}
              >
                <span className="flex min-w-0 flex-col gap-0.5">
                  <span className="truncate text-[13px] font-medium tracking-[-0.01em] text-[#17181a] dark:text-white">
                    <Match text={item.title} query={query} />
                  </span>
                  <span className="truncate text-[11px] text-[#85847e] dark:text-[#828282]">
                    {item.meta}
                  </span>
                </span>

                {index === active ? (
                  <span
                    aria-hidden="true"
                    className="shrink-0 rounded border border-[#17181a]/10 px-1.5 py-0.5 text-[10px] text-[#85847e] dark:border-white/15 dark:text-[#828282]"
                  >
                    ↵
                  </span>
                ) : null}
              </li>
            ))
          )}
        </ul>

        <div className="flex items-center gap-3 border-t border-[#17181a]/[0.06] px-3.5 py-2 text-[10px] text-[#85847e] dark:border-white/[0.08] dark:text-[#828282]">
          <span>
            <kbd className="font-sans">↑↓</kbd> move
          </span>
          <span>
            <kbd className="font-sans">↵</kbd> open
          </span>
          <span className="ml-auto">
            <kbd className="font-sans">esc</kbd> clear
          </span>
        </div>
      </div>
    </div>
  );
}

