/**
 * Bencho's `.upl-*` layer, scoped under `.upl-demo`. The source resolves
 * `--fill-slab` / `--fill-on` / `--signal` / `--ok` from its theme; here they
 * are fixed light and dark values so the block stays self-contained.
 *
 * The source draws its box edge with a 1 px stroke and hands the "dashed edge"
 * over to the catalog snippet (`stroke-dashoffset: -22` while a file is held).
 * This port keeps that dashed SVG edge permanently and lights it in the signal
 * colour on drag-over, which is the state the block is known for.
 */
export const UPLOAD_CSS = `
.upl-demo {
  --upl-slab: #ffffff;
  --upl-ink: #17181a;
  --upl-ink-3: #5c5b56;
  --upl-signal: #2231dd;
  --upl-ok: #15803d;
  --upl-red: #e5484d;
  --upl-r: 20px;
  --upl-spring: cubic-bezier(0.3, 1.36, 0.4, 1);
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
  width: 300px;
  max-width: 100%;
  color: var(--upl-ink);
  font-family: inherit;
  -webkit-user-select: none;
  user-select: none;
}
.dark .upl-demo {
  --upl-slab: #202020;
  --upl-ink: #f4f3f1;
  --upl-ink-3: #9a9a9a;
  --upl-signal: #8b96ff;
  --upl-ok: #3fb950;
  --upl-red: #ff6369;
}

.upl-input {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.upl-zone {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  height: 176px;
  padding: 0 16px;
  border-radius: var(--upl-r);
  background: var(--upl-slab);
  overflow: hidden;
  transition:
    scale 0.42s cubic-bezier(0.24, 1.34, 0.38, 1),
    background-color 0.22s ease;
}
.upl-zone[data-over] {
  scale: 1.02;
  background: color-mix(in srgb, var(--upl-signal) 5%, var(--upl-slab));
}
.upl-zone[data-gulp] {
  animation: upl-gulp 0.46s cubic-bezier(0.3, 1.2, 0.4, 1);
}
.upl-zone[data-gulp] .upl-icon {
  animation: upl-open 0.46s cubic-bezier(0.3, 1.4, 0.4, 1);
}
.upl-zone[data-shake] {
  animation: upl-shake 0.42s ease;
}

.upl-dash {
  position: absolute;
  inset: 0.5px;
  width: calc(100% - 1px);
  height: calc(100% - 1px);
  pointer-events: none;
}
.upl-dash rect {
  fill: none;
  stroke: color-mix(in srgb, var(--upl-ink) 26%, transparent);
  stroke-width: 1;
  stroke-dasharray: 5 6;
  transition: stroke 0.22s ease;
}
.upl-zone[data-over] .upl-dash rect {
  stroke: var(--upl-signal);
  animation: upl-march 700ms linear infinite;
}
.upl-zone[data-refuse] .upl-dash rect {
  stroke: var(--upl-red);
}

.upl-pick {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  height: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.upl-pick:focus-visible {
  outline: 2px solid var(--upl-signal);
  outline-offset: -5px;
  border-radius: calc(var(--upl-r) - 5px);
}

.upl-icon {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--upl-ink) 6%, var(--upl-slab));
  color: color-mix(in srgb, var(--upl-ink) 72%, var(--upl-slab));
  transition:
    translate 0.42s cubic-bezier(0.24, 1.34, 0.38, 1),
    background-color 0.22s ease,
    color 0.22s ease;
}
.upl-zone[data-over] .upl-icon {
  color: var(--upl-ink);
  translate: 0 -4px;
  background: color-mix(in srgb, var(--upl-signal) 12%, var(--upl-slab));
}

.upl-say {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  font-size: 13px;
  line-height: 1.2;
  text-align: center;
  letter-spacing: 0;
}
.upl-say b {
  font-weight: 500;
}
.upl-say span {
  font-size: 12px;
  color: var(--upl-ink-3);
