/*
 * Bencho morphs the play triangle into a pause pair instead of swapping glyphs.
 * The two point sets are copied from the source; each frame interpolates the
 * eight coordinates and writes one path. `on` means the clip is playing.
 */
const PLAY = [
  [7, 4, 13, 7.6, 13, 16.4, 7, 20],
  [13, 7.6, 19, 12, 19, 12, 13, 16.4],
] as const;
const PAUSE = [
  [7, 5, 10.5, 5, 10.5, 19, 7, 19],
  [13.5, 5, 17, 5, 17, 19, 13.5, 19],
] as const;

function morphPath(t: number) {
  return PLAY.map((shape, index) => {
    const points = shape.map((value, point) =>
      (value + (PAUSE[index][point] - value) * t).toFixed(2),
    );
    return `M${points[0]} ${points[1]}L${points[2]} ${points[3]}L${points[4]} ${points[5]}L${points[6]} ${points[7]}Z`;
  }).join("");
}

export function PlayPauseIcon({
  playing,
  reduced,
}: {
  playing: boolean;
  reduced: boolean;
}) {
  const [t, setT] = useState(playing ? 1 : 0);
  const target = useRef(playing ? 1 : 0);
  target.current = playing ? 1 : 0;

  useEffect(() => {
    if (reduced) {
      setT(target.current);
      return;
    }

    const from = t;
    const to = target.current;
    const start = performance.now();
    let frame = 0;

    const tick = (now: number) => {
      const progress = Math.min(1, (now - start) / 220);
      setT(from + (to - from) * (1 - (1 - progress) ** 4));
      if (progress < 1) frame = requestAnimationFrame(tick);
    };

    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
    // `t` is only the starting point of a new morph; re-running on every frame
    // would restart the ease. The target is read from the ref instead.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [playing, reduced]);

  return (
    <svg
      width="20"
      height="20"
      viewBox="0 0 24 24"
      aria-hidden="true"
      focusable="false"
    >
      <path
        d={morphPath(t)}
        fill="currentColor"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/**
 * Bencho's Voice note cues, rebuilt from the `press`, `pop`, `tock`, `click`
 * and `whisk` voice tables in its sound engine. The AudioContext is created
 * lazily inside the gesture that needs it, so nothing touches `window` during
 * render or module load.
 */

type Voice = {
  hz: number;
  to?: number;
  ms: number;
  gain: number;
  wave: OscillatorType;
  cut?: number;
  atk: number;
};

export type VoiceSound = "press" | "pop" | "tock" | "click" | "whisk";

const VOICES: Record<VoiceSound, readonly Voice[]> = {
  // 168 Hz, 95 ms sine, 480 Hz lowpass, 14 ms attack
  press: [{ hz: 168, ms: 95, gain: 0.028, wave: "sine", cut: 480, atk: 14 }],
  // 680 -> 930 Hz, 34 ms sine
  pop: [{ hz: 680, to: 930, ms: 34, gain: 0.05, wave: "sine", atk: 3 }],
  // 250 Hz, 28 ms triangle through a 1.7 kHz lowpass
  tock: [
    { hz: 250, ms: 28, gain: 0.045, wave: "triangle", cut: 1700, atk: 10 },
  ],
  // 196 -> 130 Hz, 150 ms sine through a 900 Hz lowpass
  click: [
    { hz: 196, to: 130, ms: 150, gain: 0.07, wave: "sine", cut: 900, atk: 6 },
  ],
  // 124 -> 65 Hz, 130 ms sine, 560 Hz lowpass, 50 ms attack
  whisk: [
    { hz: 124, to: 65, ms: 130, gain: 0.067, wave: "sine", cut: 560, atk: 50 },
  ],
};

let context: AudioContext | null = null;

function getContext(): AudioContext | null {
  if (typeof window === "undefined") return null;
  if (context) return context;

  const Ctor =
    window.AudioContext ??
    (window as unknown as { webkitAudioContext?: typeof AudioContext })
      .webkitAudioContext;
  if (!Ctor) return null;

  try {
    context = new Ctor();
  } catch {
    return null;
  }
  return context;
}

function emit(ctx: AudioContext, voice: Voice) {
  const start = ctx.currentTime;
  const duration = voice.ms / 1000;
  const attack = Math.min(voice.atk / 1000, duration * 0.6);

  const oscillator = ctx.createOscillator();
  oscillator.type = voice.wave;
  oscillator.frequency.setValueAtTime(voice.hz, start);
  if (voice.to) {
    oscillator.frequency.exponentialRampToValueAtTime(
      voice.to,
      start + duration,
    );
  }

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(1e-4, start);
  gain.gain.exponentialRampToValueAtTime(voice.gain, start + attack);
  gain.gain.exponentialRampToValueAtTime(1e-4, start + duration);

  let tail: AudioNode = oscillator;
  if (voice.cut) {
    const filter = ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = voice.cut;
    oscillator.connect(filter);
    tail = filter;
  }

  tail.connect(gain);
  gain.connect(ctx.destination);

  oscillator.start(start);
  oscillator.stop(start + duration + 0.02);
}

export function playVoiceSound(name: VoiceSound) {
  const ctx = getContext();
  if (!ctx) return;

  // Safari can return a suspended context even inside a gesture; scheduling at
  // the frozen currentTime means the tone starts as soon as it resumes.
  if (ctx.state === "suspended") {
    void ctx.resume();
  }

  for (const voice of VOICES[name]) {
    emit(ctx, voice);
  }
}

